mapper.update:
UPDATE appr_decision_outbox
SET status = 'PUBLISHED',
    published_at = #{now},
    lease_owner = NULL,
    lease_until = NULL,
    last_error = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'IN_FLIGHT'
  AND lease_owner = #{workerId}

UPDATE appr_decision_outbox
SET status = 'PENDING',
    next_attempt_at = #{nextAttemptAt},
    lease_owner = NULL,
    lease_until = NULL,
    last_error = #{lastError},
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'IN_FLIGHT'
  AND lease_owner = #{workerId}
